// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c) && caller != address(0));
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        uint balanceBefore = address(c).balance;
        (bool ok, ) = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));
        vm.assume(ok);
        uint balanceAfter = address(c).balance;
        assertTrue((balanceAfter == 0) || (balanceAfter == 10));
    }
}

